/// `base` (a `Z` text) plus `seconds`, as the C# `DateTime.AddSeconds`.
fn utc_plus(base: &str, seconds: i64) -> DateTimeUtc {
    let (value, _) = DateTimeUtc::parse_json(base).expect("base text parses");
    value
        .checked_add_ticks(seconds * TICKS_PER_SECOND)
        .expect("test stamps stay in range")
}

fn journal_plus(base: &str, seconds: i64) -> JournalDateTime {
    JournalDateTime::utc(utc_plus(base, seconds))
}

/// C# `Encoding.UTF8.GetBytes(JsonSerializer.Serialize(entry) + "\r\n")`.
fn crlf_line(entry: &JournalEntry) -> Vec<u8> {
    format!("{}\r\n", entry.to_line()).into_bytes()
}

/// C# `Concat(...)`.
fn concat(lines: &[Vec<u8>]) -> Vec<u8> {
    lines.concat()
}

/// C# `Encoding.UTF8.GetBytes(text)`.
fn bytes(text: &str) -> Vec<u8> {
    text.as_bytes().to_vec()
}

fn decode_hex(text: &str) -> Vec<u8> {
    assert!(text.len() % 2 == 0, "hex text has an odd length");
    text.as_bytes()
        .chunks(2)
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).expect("hex is ASCII"), 16).expect("hex digits"))
        .collect()
}

/// A golden byte field: `<key>_hex` when present, else `<key>_text` as UTF-8.
fn case_bytes(case: &Value, key: &str) -> Vec<u8> {
    match case.get(format!("{key}_hex").as_str()).and_then(Value::as_str) {
        Some(hex) => decode_hex(hex),
        None => bytes(str_of(case, &format!("{key}_text"))),
    }
}

/// C# `JournalCompactionPlanTests.Entry` (and the Reprepare file's copy): source `C:\photos\<id>.jpg`, destination
/// `C:\photos\sel\<id>.jpg`, size 1, LastWriteUtc = base, TimestampUtc = base + `tick` seconds, `Error` "boom" iff a code.
fn entry_at(
    base: &str,
    id: &str,
    op: FileOperationType,
    state: JournalState,
    tick: i64,
    error_code: Option<&str>,
) -> JournalEntry {
    JournalEntry {
        id: id.to_owned(),
        op_type: op,
        state,
        source: format!(r"C:\photos\{id}.jpg"),
        destination: Some(format!(r"C:\photos\sel\{id}.jpg")),
        size: 1,
        last_write_utc: journal_plus(base, 0),
        timestamp_utc: journal_plus(base, tick),
        error: error_code.map(|_| "boom".to_owned()),
        error_code: error_code.map(str::to_owned),
        permanent: None,
        undo: None,
        group_id: None,
        group_members: None,
    }
}

const BASE: &str = "2026-09-25T00:00:00Z";

fn entry(id: &str, op: FileOperationType, state: JournalState, tick: i64, error_code: Option<&str>) -> JournalEntry {
    entry_at(BASE, id, op, state, tick, error_code)
}

