// C#: JournalCompactionPlanTests.Build_PreparedThenCommitted_OnlyCommittedKept
#[test]
fn build_prepared_then_committed_only_committed_kept() {
    let p = entry("a", Copy, Prepared, 0, None);
    let c = entry("a", Copy, Committed, 1, None);
    let input = concat(&[crlf_line(&p), crlf_line(&c)]);

    let result = build(&input);

    assert_eq!(result.dropped_lines, 1);
    assert_eq!(result.kept_lines, 1);
    assert_eq!(result.kept, crlf_line(&c));
}

