// C#: JournalCompactionPlanTests.Build_InnerCarriageReturnInSupersedingLine_EarlierPreparedKept
#[test]
fn build_inner_carriage_return_in_superseding_line_earlier_prepared_kept() {
    let p = entry("a", Copy, Prepared, 0, None);
    let c = entry("a", Copy, Committed, 1, None);
    let c_json = c.to_line();
    // Inject a raw '\r' right after the opening brace (valid JSON whitespace, but not the line terminator): the
    // plan must never recognize it as an entry.
    let mut c_with_inner_cr = b"{\r".to_vec();
    c_with_inner_cr.extend_from_slice(&c_json.as_bytes()[1..]);
    c_with_inner_cr.extend_from_slice(b"\r\n");
    let input = concat(&[crlf_line(&p), c_with_inner_cr]);

    let result = build(&input);

    assert_eq!(result.dropped_lines, 0);
    assert_eq!(result.kept, input);
}

// ---------------------------------------------------------------------------------------------------------------
// Committed-Move tail window.
// ---------------------------------------------------------------------------------------------------------------

fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
    !needle.is_empty() && haystack.windows(needle.len()).any(|window| window == needle)
}

/// A CRLF-terminated line without its terminator.
fn without_crlf(line: &[u8]) -> &[u8] {
    &line[..line.len() - 2]
}

// C#: JournalCompactionPlanTests.Build_CommittedMoveWindow_OnlyLast200Kept
#[test]
fn build_committed_move_window_only_last_200_kept() {
    const IDS: usize = 250;
    let mut lines: Vec<Vec<u8>> = Vec::new();
    let mut committed_lines: Vec<Vec<u8>> = Vec::with_capacity(IDS);
    for i in 0..IDS {
        let id = format!("m{i}");
        let c = entry(&id, Move, Committed, (i * 2) as i64, None);
        let d = entry(&id, Move, Dismissed, (i * 2 + 1) as i64, None);
        committed_lines.push(crlf_line(&c));
        lines.push(crlf_line(&c));
        lines.push(crlf_line(&d));
    }
    let input = concat(&lines);

    let result = build(&input);

    // Dropped: the first 50 Committed lines (ids 0..49) that fell out of the 200-line tail window.
    assert_eq!(result.dropped_lines, 50);
    assert_eq!(result.kept_lines, 2 * IDS - 50);
    for committed in &committed_lines[..50] {
        assert!(!contains_slice(&result.kept, without_crlf(committed)));
    }
    for committed in &committed_lines[50..] {
        assert!(contains_slice(&result.kept, without_crlf(committed)));
    }
}

// C#: JournalCompactionPlanTests.Build_KeptLines_PreserveOrderAndExactBytes
#[test]
fn build_kept_lines_preserve_order_and_exact_bytes() {
    let p1 = entry("a", Copy, Prepared, 0, None);
    let c1 = entry("a", Copy, Committed, 1, None);
    let p2 = entry("b", Move, Prepared, 2, None);
    let f2 = entry("b", Move, Failed, 3, None);
    let input = concat(&[crlf_line(&p1), crlf_line(&c1), crlf_line(&p2), crlf_line(&f2)]);

    let result = build(&input);

    assert_eq!(result.kept, concat(&[crlf_line(&c1), crlf_line(&p2), crlf_line(&f2)]));
}

// ---------------------------------------------------------------------------------------------------------------
// Observational equivalence: compacted must be indistinguishable from the original through every read API.
// ---------------------------------------------------------------------------------------------------------------

/// C# `HistoryKind`.
#[derive(Clone, Copy, Debug)]
enum HistoryKind {
    PreparedCommitted,
    PreparedFailed,
    PreparedFailedDismissed,
    RetryPreparedFailedPreparedCommitted,
    Fa01Residue,
}

const HISTORY_KINDS: [HistoryKind; 5] = [
    HistoryKind::PreparedCommitted,
    HistoryKind::PreparedFailed,
    HistoryKind::PreparedFailedDismissed,
    HistoryKind::RetryPreparedFailedPreparedCommitted,
    HistoryKind::Fa01Residue,
];

/// C# `BuildHistory`: the lines of one Id in append order. `tick` is the shared counter (C# `ref int`).
fn build_history(id: &str, op: FileOperationType, kind: HistoryKind, tick: &mut i64) -> Vec<JournalEntry> {
    let mut next = |state: JournalState, code: Option<&str>| {
        let e = entry(id, op, state, *tick, code);
        *tick += 1;
        e
    };
    match kind {
        HistoryKind::PreparedCommitted => vec![next(Prepared, None), next(Committed, None)],
        HistoryKind::PreparedFailed => vec![next(Prepared, None), next(Failed, None)],
        HistoryKind::PreparedFailedDismissed => {
            vec![next(Prepared, None), next(Failed, None), next(Dismissed, None)]
        }
        HistoryKind::RetryPreparedFailedPreparedCommitted => {
            vec![
                next(Prepared, None),
                next(Failed, None),
                next(Prepared, None),
                next(Committed, None),
            ]
        }
        HistoryKind::Fa01Residue => {
            vec![
                next(Prepared, None),
                next(Committed, None),
                next(Failed, Some(PENDING_UNCONFIRMED)),
            ]
        }
    }
}

/// C# `GeneratedJournal`.
struct GeneratedJournal {
    original: Vec<u8>,
    compacted: Vec<u8>,
    history_by_id: Vec<(String, Vec<JournalEntry>)>,
}

/// Deterministic xorshift64 written in the test (no `rand` crate). C# `System.Random` sequences need not be reproduced:
/// the property under test is seed-independent.
struct XorShift(u64);

impl XorShift {
    fn new(seed: u64) -> Self {
        Self(seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1)
    }

    fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }

    fn below(&mut self, bound: usize) -> usize {
        (self.next_u64() % bound as u64) as usize
    }
}

/// C# `Generate(seed, idCount, allMoveType)`.
fn generate(seed: u64, id_count: usize, all_move: bool) -> GeneratedJournal {
    let mut rng = XorShift::new(seed);
    let mut tick = 0i64;
    let mut history_by_id: Vec<(String, Vec<JournalEntry>)> = Vec::with_capacity(id_count);
    let mut pending: Vec<(String, VecDeque<JournalEntry>)> = Vec::with_capacity(id_count);

    for i in 0..id_count {
        let id = format!("id{i}");
        let op = if all_move {
            Move
        } else {
            match i % 3 {
                0 => Move,
                1 => Copy,
                _ => Recycle,
            }
        };
        let kind = HISTORY_KINDS[rng.below(HISTORY_KINDS.len())];
        let history = build_history(&id, op, kind, &mut tick);
        history_by_id.push((id.clone(), history.clone()));
        pending.push((id, history.into()));
    }

    // Random interleaving that preserves each Id's own append order, plus scattered blank and unparseable lines.
    let mut lines: Vec<Vec<u8>> = Vec::new();
    while !pending.is_empty() {
        let index = rng.below(pending.len());
        let (_, queue) = &mut pending[index];
        let next = queue.pop_front().expect("a pending queue is never empty");
        let exhausted = queue.is_empty();
        lines.push(crlf_line(&next));
        if exhausted {
            pending.remove(index);
        }
        if rng.below(15) == 0 {
            lines.push(b"\r\n".to_vec()); // blank
        }
        if rng.below(15) == 0 {
            lines.push(format!("garbage-{}\r\n", rng.next_u64() as u32).into_bytes()); // unparseable
        }
    }

    let original = concat(&lines);
    let compacted = build(&original).kept;
    GeneratedJournal {
        original,
        compacted,
        history_by_id,
    }
}

fn paths() -> AppPaths {
    AppPaths::new(Path::new(r"C:\Users\test\AppData\Local"), None, false)
}

/// C# `FakeClock(BaseTime.AddDays(1))`.
fn clock() -> Arc<FakeClock> {
    Arc::new(FakeClock::at(utc_plus(BASE, 86_400)))
}

/// C# `MakeJournal`: an in-memory journal file holding exactly `bytes`.
fn make_journal(bytes: &[u8], paths: &AppPaths, clock: Arc<FakeClock>) -> OperationJournal {
    let fs = Arc::new(FakeFileSystem::new());
    fs.add_file(&paths.journal_file, bytes);
    OperationJournal::new(paths, fs, clock)
}

/// C# `AppendIfUnchangedSinceFresh`: a fresh journal, one guarded append.
fn append_fresh(
    bytes: &[u8],
    paths: &AppPaths,
    clock: &Arc<FakeClock>,
    anchor: &JournalEntry,
    own_since: &[JournalEntry],
    fresh: &JournalEntry,
) -> bool {
    let journal = make_journal(bytes, paths, clock.clone());
    journal
        .append_if_unchanged_since(anchor, own_since, fresh)
        .expect("guarded append reads the journal")
}

/// C# `DismissFresh`: a fresh journal, one dismiss of `entry`.
fn dismiss_fresh(bytes: &[u8], paths: &AppPaths, clock: &Arc<FakeClock>, entry: &JournalEntry) -> DismissOutcome {
    let journal = make_journal(bytes, paths, clock.clone());
    journal
        .dismiss(std::slice::from_ref(entry))
        .expect("dismiss reads the journal")
}

/// C# `ReadPendingOperations` (test-only extension): Prepared entries, sorted by Id (ordinal).
fn read_pending_sorted(journal: &OperationJournal) -> Vec<JournalEntry> {
    let mut entries: Vec<JournalEntry> = journal
        .read_pending_and_failed_operations()
        .expect("read pending and failed")
        .into_iter()
        .filter(|e| e.state == Prepared)
        .collect();
    entries.sort_by(|a, b| a.id.cmp(&b.id));
    entries
}

/// C# `ReadFailedOperations` (test-only extension): Failed entries, sorted by Id (ordinal).
fn read_failed_sorted(journal: &OperationJournal) -> Vec<JournalEntry> {
    let mut entries: Vec<JournalEntry> = journal
        .read_pending_and_failed_operations()
        .expect("read pending and failed")
        .into_iter()
        .filter(|e| e.state == Failed)
        .collect();
    entries.sort_by(|a, b| a.id.cmp(&b.id));
    entries
}

fn assert_is_subsequence(shorter: &[JournalEntry], longer: &[JournalEntry]) {
    let mut j = 0;
    for entry in shorter {
        while j < longer.len() && longer[j] != *entry {
            j += 1;
        }
        assert!(
            j < longer.len(),
            "entry {}/{:?} of the original result is missing from the compacted result",
            entry.id,
            entry.state
        );
        j += 1;
    }
}

fn assert_observational_equivalence(seed: u64, id_count: usize) {
    let generated = generate(seed, id_count, false);
    let paths = paths();
    let clock = clock();

    let original = make_journal(&generated.original, &paths, clock.clone());
    let compacted = make_journal(&generated.compacted, &paths, clock.clone());

    assert_eq!(
        original.read_pending_and_failed_operations().expect("read"),
        compacted.read_pending_and_failed_operations().expect("read")
    );
    assert_eq!(read_pending_sorted(&original), read_pending_sorted(&compacted));
    assert_eq!(read_failed_sorted(&original), read_failed_sorted(&compacted));

    let original_moves = original.read_committed_moves().expect("read committed moves");
    let compacted_moves = compacted.read_committed_moves().expect("read committed moves");
    assert_is_subsequence(&original_moves, &compacted_moves);

    for (id, history) in &generated.history_by_id {
        let mut anchors = history.clone();
        anchors.push(entry(id, Move, Prepared, 999_999, None)); // fabricated, never appended
        let mut own_since_options: Vec<Vec<JournalEntry>> = vec![Vec::new()];
        for prepared in history.iter().filter(|e| e.state == Prepared) {
            own_since_options.push(vec![prepared.clone()]);
        }
        own_since_options.push(vec![entry(id, Copy, Prepared, 999_998, None)]);

        for anchor in &anchors {
            for own_since in &own_since_options {
                let fresh = entry(id, Copy, Committed, 999_997, None);
                let original_outcome = append_fresh(&generated.original, &paths, &clock, anchor, own_since, &fresh);
                let compacted_outcome = append_fresh(&generated.compacted, &paths, &clock, anchor, own_since, &fresh);
                assert_eq!(
                    original_outcome,
                    compacted_outcome,
                    "Id={id} anchor={:?} ownSince.Count={}",
                    anchor.state,
                    own_since.len()
                );
            }
        }

        let latest = history.last().expect("history is never empty");
        let older = history.first().expect("history is never empty");
        assert_eq!(
            dismiss_fresh(&generated.original, &paths, &clock, latest),
            dismiss_fresh(&generated.compacted, &paths, &clock, latest)
        );
        if older != latest {
            assert_eq!(
                dismiss_fresh(&generated.original, &paths, &clock, older),
                dismiss_fresh(&generated.compacted, &paths, &clock, older)
            );
        }
    }
}

